import java.util.Scanner;
import java.util.function.LongPredicate;

public class Main {
    static long cube(long x) {
        return x * x * x;
    }

    static long foo(long n) {
        long ans = 0;
        for (long k = 2; ; k++) {
            long x = n / cube(k);
            if (x == 0) break;
            ans += x;
        }
        return ans;
    }

    static long binSearch(LongPredicate f, long lo, long up, long eps) {
        up++;
        long cnt = up - lo;
        long mid, step;
        while (cnt >= eps) {
            step = cnt / 2;
            mid = lo + step;
            if (!f.test(mid)) {
                lo = mid + eps;
                cnt -= step + eps;
            } else {
                cnt = step;
            }
        }
        return lo;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long m = sc.nextLong();
        long mx = 4949100894494448L;

        long p = binSearch(n -> foo(n) >= m, 1, mx, 1);

        if (foo(p) != m) {
            p = -1;
        }

        System.out.println(p);
    }
}

